"""Generate docs/test-catalog/<system>.md: every discovered test class and method per system.

Usage: python tools/gen_test_catalog.py
"""

import sys

from gen_suites import module_title, plan
from systems import CATALOG_DOC_ROOT, SYSTEMS
from testsource import discover


def _cell(text):
    return (text or "").replace("|", "\\|").replace("\n", " ")


def render(system, entries):
    title = SYSTEMS[system]["title"]
    blocks = plan(system, entries)
    methods = sum(len(e["methods"]) for e in entries)
    lines = [
        "# Test catalog - " + title,
        "",
        "GENERATED by `tools/gen_test_catalog.py` from Java sources - do not edit by hand.",
        "",
        "- System key: `%s` (run with `-Dactive.system=%s`)" % (system, system),
        "- Test classes: %d, test methods: %d" % (len(entries), methods),
        "- Whole suite: `suites/%s.xml` (%s)" % (system, ", ".join(name for name, _ in blocks)),
        "",
    ]
    by_module = {}
    for entry in entries:
        by_module.setdefault(entry["module"], []).append(entry)
    for module in sorted(by_module):
        lines += ["## %s (`%s`)" % (module_title(system, module), module), ""]
        for entry in by_module[module]:
            lines += ["### `%s`" % entry["simple"], "", "Source: `%s`" % entry["path"], "",
                      "| Test ID | Method | Description | Severity | Manual cases covered | Enabled |",
                      "|---|---|---|---|---|---|"]
            for method in entry["methods"]:
                lines.append("| %s | `%s` | %s | %s | %s | %s |" % (
                    _cell(method["id"]), method["name"], _cell(method["description"]), method["severity"],
                    _cell(", ".join(method["covers"])), "yes" if method["enabled"] else "no"))
            lines.append("")
    return "\n".join(lines)


def main():
    CATALOG_DOC_ROOT.mkdir(parents=True, exist_ok=True)
    for system, entries in discover().items():
        path = CATALOG_DOC_ROOT / (system + ".md")
        path.write_text(render(system, entries), encoding="utf-8", newline="\n")
        print("%s: %d classes -> %s" % (system, len(entries), path.relative_to(path.parents[2]).as_posix()))
    return 0


if __name__ == "__main__":
    sys.exit(main())
